def _validate_braces(self, format):
    """Validate that all braces are properly matched and enclosed."""
    i = 0
    while i < len(format):
        if format[i] == '{':
            # Found an opening brace - must find closing brace
            j = i + 1
            depth = 1
            while j < len(format) and depth > 0:
                if format[j] == '{':
                    depth += 1
                elif format[j] == '}':
                    depth -= 1
                j += 1
            if depth != 0:
                raise ValueError("Format string has unmatched opening brace at position %d" % i)
            # Skip past the closing brace we just found
            i = j
        elif format[i] == '}':
            # Found a closing brace without matching opening
            raise ValueError("Format string has unmatched closing brace at position %d" % i)
        else:
            i += 1

